import{avatarPath,imageKind,AVATAR_BYTES}from './account-avatar-core.js';
export const AVATAR_BUCKET='profile-avatars';
export function createAvatarStore({getClient,now=Date.now,createUrl=blob=>URL.createObjectURL(blob),revokeUrl=url=>URL.revokeObjectURL(url)}){const cache=new Map(),revisions=new Map();let generation=0;
 const invalidate=uid=>{const entry=cache.get(uid);if(entry?.url)revokeUrl(entry.url);cache.delete(uid);revisions.set(uid,(revisions.get(uid)||0)+1);};
 async function sessionFor(uid){const client=getClient(),{data,error}=await client.auth.getSession();if(error||!data?.session?.user?.email_confirmed_at||data.session.user.is_anonymous||avatarPath(data.session.user.id)!==avatarPath(uid))throw Error('sign_in_required');return client;}
 return {invalidate,clear(){generation++;for(const uid of [...cache.keys()])invalidate(uid);},async get(uid){avatarPath(uid);const token=generation,client=await sessionFor(uid);if(token!==generation)throw Error('request_changed');const stored=cache.get(uid);if(stored?.promise)return stored.promise;if(stored&&stored.until>now())return stored.url;invalidate(uid);const revision=revisions.get(uid);const current=()=>token===generation&&revision===revisions.get(uid);
 const promise=(async()=>{const {data,error}=await client.storage.from(AVATAR_BUCKET).download(avatarPath(uid));if(!current())throw Error('request_changed');if(error){if([400,404].includes(Number(error.statusCode||error.status))||/not found|does not exist/i.test(error.message||'')){cache.set(uid,{url:null,until:now()+30000});return null;}throw Error('photo_unavailable');}if(!data||data.size>AVATAR_BYTES||await imageKind(data)!=='jpeg')throw Error('photo_unavailable');if(!current())throw Error('request_changed');const url=createUrl(new Blob([data],{type:'image/jpeg'}));cache.set(uid,{url,until:now()+30000});return url;})();cache.set(uid,{promise});try{return await promise;}catch(e){if(current())cache.delete(uid);throw e;}},async save(uid,blob){if(!blob||blob.type!=='image/jpeg'||blob.size>AVATAR_BYTES||await imageKind(blob)!=='jpeg')throw Error('export_size');const client=await sessionFor(uid);const {error}=await client.storage.from(AVATAR_BUCKET).upload(avatarPath(uid),blob,{contentType:'image/jpeg',cacheControl:'0',upsert:true});if(error)throw Error('photo_unavailable');invalidate(uid);return true;},async remove(uid){const client=await sessionFor(uid);const {error}=await client.storage.from(AVATAR_BUCKET).remove([avatarPath(uid)]);if(error)throw Error('photo_unavailable');invalidate(uid);cache.set(uid,{url:null,until:now()+30000});return true;}};
}
